PARAMETERS pT Text ( 50 ), pId Long;
UPDATE Items SET Txt = pT
WHERE ID = pId;

PARAMETERS pB Text ( 10 ), pA Long, pC Currency, pD DateTime, pY Bit;
SELECT ID, Code, L, C, Dt, Y
FROM Items
WHERE L = pA OR Code = pB OR C = pC OR Dt = pD OR Y = pY;

PARAMETERS pCode Text ( 10 );
SELECT ID, Code, Txt
FROM Items
WHERE Code = pCode;

SELECT ID, Code
FROM Items
ORDER BY ID;
